UPDATE EXECUTION_BATCH
SET BATCH_STATUS = #{nextStatus},
    FINISHED_AT = CASE
        WHEN #{nextStatus} IN (
            'SUCCESS', 'FAILED', 'PARTIAL_FAILED'
        ) THEN SYSTIMESTAMP
        ELSE NULL
    END
WHERE BATCH_ID = #{batchId}
  AND BATCH_STATUS = #{expectedStatus}

mapper.select:
SELECT COUNT(*)
FROM EXECUTION_BATCH
WHERE REQUEST_ID = #{requestId}

