UPDATE QUERY_REQUEST
SET REQUEST_STATUS = #{nextStatus}
WHERE REQUEST_ID = #{requestId}
  AND REQUEST_STATUS = #{expectedStatus}
  AND APPROVAL_STATUS = 'APPROVED'
